import{c as t,Q as d,j as o,m as c}from"./chunks/framework.t4rEqR7d.js";const h=JSON.parse('{"title":"pagentv5 resource endpoints","description":"","frontmatter":{},"headers":[],"relativePath":"pagentv5/resource-endpoints.md","filePath":"pagentv5/resource-endpoints.md"}'),r={name:"pagentv5/resource-endpoints.md"};function s(a,e,i,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="pagentv5-resource-endpoints" tabindex="-1">pagentv5 resource endpoints <a class="header-anchor" href="#pagentv5-resource-endpoints" aria-label="Permalink to &quot;pagentv5 resource endpoints&quot;">​</a></h1><p>pagentv5 将 Task、Session、Sandbox、UserDir 的实现放在传输层下面。CLI 可以直接 调用 Python 方法，Wire、HTTP、RPC 和 Desktop IPC 可以在这些方法外包装参数校验、 鉴权与序列化。</p><p>统一实现入口是 <code>pagentv5.service.ResourceService</code>。机器可读清单由 <code>pagentv5.service.endpoint_inventory()</code> 返回。</p><h2 id="resource-endpoints" tabindex="-1">Resource endpoints <a class="header-anchor" href="#resource-endpoints" aria-label="Permalink to &quot;Resource endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>实现函数</th><th>返回</th></tr></thead><tbody><tr><td><code>task.create</code></td><td><code>ResourceService.create_task</code></td><td>Task 详情</td></tr><tr><td><code>task.open</code></td><td><code>ResourceService.open_task</code></td><td>Task 详情</td></tr><tr><td><code>task.list</code></td><td><code>ResourceService.list_tasks</code></td><td>Task 摘要列表</td></tr><tr><td><code>task.get</code></td><td><code>ResourceService.task_details</code></td><td>配置、元信息、工具能力</td></tr><tr><td><code>task.metadata.update</code></td><td><code>ResourceService.update_task_metadata</code></td><td>更新后的元信息</td></tr><tr><td><code>task.delete</code></td><td><code>ResourceService.delete_task</code></td><td>无；当前实现为软删除</td></tr><tr><td><code>session.get</code></td><td><code>ResourceService.session_messages</code></td><td>结构化消息列表</td></tr><tr><td><code>session.replace</code></td><td><code>ResourceService.replace_session</code></td><td>保存后的消息列表</td></tr><tr><td><code>session.clear</code></td><td><code>ResourceService.clear_session</code></td><td>无</td></tr><tr><td><code>sandbox.status</code></td><td><code>ResourceService.sandbox_status</code></td><td>backend、alive、workdir</td></tr><tr><td><code>sandbox.tree</code></td><td><code>ResourceService.sandbox_tree</code></td><td>工作根文件树</td></tr><tr><td><code>sandbox.file.read</code></td><td><code>ResourceService.read_sandbox_file</code></td><td>bytes</td></tr><tr><td><code>userdir.status</code></td><td><code>ResourceService.userdir_status</code></td><td>access、path</td></tr><tr><td><code>userdir.tree</code></td><td><code>ResourceService.userdir_tree</code></td><td>用户目录文件树</td></tr><tr><td><code>userdir.file.read</code></td><td><code>ResourceService.read_userdir_file</code></td><td>bytes</td></tr><tr><td><code>task.capabilities</code></td><td><code>ResourceService.capabilities</code></td><td>Provider、工具和资源摘要</td></tr><tr><td><code>run.start</code></td><td><code>ResourceService.run</code></td><td><code>RunnerEvent</code> 异步流</td></tr><tr><td><code>run.cancel</code></td><td><code>ResourceService.cancel_run</code></td><td>是否找到活动运行</td></tr></tbody></table><p><code>run.start</code> 会从 Task 取得 Provider 配置、Sandbox/UserDir 投影工具和 Session 历史。运行结束后，Runner 的完整 Provider 输入会写回 Session。</p><h2 id="existing-wire-commands" tabindex="-1">Existing Wire commands <a class="header-anchor" href="#existing-wire-commands" aria-label="Permalink to &quot;Existing Wire commands&quot;">​</a></h2><p>现有 <code>src/app/wire.py</code> 接收以下命令。Task 命名替代 Thread 命名后，资源命令按下表 迁移。</p><table tabindex="0"><thead><tr><th>Wire command</th><th>新 endpoint / 归属</th></tr></thead><tbody><tr><td><code>reset</code></td><td><code>task.create</code></td></tr><tr><td><code>resume</code></td><td><code>task.open</code></td></tr><tr><td><code>list_threads</code></td><td><code>task.list</code></td></tr><tr><td><code>thread_meta</code></td><td><code>task.get</code></td></tr><tr><td><code>delete_thread</code></td><td><code>task.delete</code></td></tr><tr><td><code>history</code></td><td><code>session.get</code></td></tr><tr><td><code>sandbox_status</code></td><td><code>sandbox.status</code></td></tr><tr><td><code>sandbox_tree</code></td><td><code>sandbox.tree</code></td></tr><tr><td><code>capabilities</code></td><td><code>task.capabilities</code></td></tr><tr><td><code>user</code></td><td><code>run.start</code></td></tr><tr><td><code>cancel</code></td><td><code>run.cancel</code></td></tr><tr><td><code>handoff_provider</code></td><td>Runtime control；后续接入 Task 的 Provider handoff 记录</td></tr><tr><td><code>permit</code> / <code>deny</code></td><td>Runtime approval；接入工具执行前 hook</td></tr><tr><td><code>commands</code></td><td>Application command catalog</td></tr><tr><td><code>client_features</code></td><td>Transport session negotiation</td></tr><tr><td><code>get_config</code></td><td>Application config service</td></tr><tr><td><code>set_provider</code></td><td>Application config service；凭据不写入 Task</td></tr><tr><td><code>environment_check</code></td><td>Host environment service</td></tr><tr><td><code>skills</code></td><td>Skill registry service</td></tr></tbody></table><p>Wire 输出仍包含运行事件，以及控制事件 <code>HistoryReplay</code>、<code>CurrentThread</code>、<code>ThreadList</code>、<code>ThreadMeta</code>、<code>ThreadTitle</code>、 <code>SandboxStatus</code>、<code>SandboxTree</code>、<code>Capabilities</code>、<code>Skills</code>、<code>SlashCommands</code>、 <code>SlashResult</code>、<code>ProviderState</code>、<code>ProviderHandoff</code>、<code>ConfigSnapshot</code>、 <code>EnvironmentCheck</code>、<code>PermitRequest</code>、<code>SubagentEvent</code> 和 <code>Error</code>。</p><p>新传输层应将其中的 Thread 字段改成 Task 字段：</p><table tabindex="0"><thead><tr><th>旧事件</th><th>新事件名</th></tr></thead><tbody><tr><td><code>CurrentThread</code></td><td><code>CurrentTask</code></td></tr><tr><td><code>ThreadList</code></td><td><code>TaskList</code></td></tr><tr><td><code>ThreadMeta</code></td><td><code>TaskMeta</code></td></tr><tr><td><code>ThreadTitle</code></td><td><code>TaskTitle</code></td></tr><tr><td><code>HistoryReplay</code></td><td>保留；字段使用 <code>task_id</code></td></tr></tbody></table><p>模型运行事件直接编码 <code>pagentv5.events.RunnerEvent</code>，事件名取 <code>type</code>，payload 使用 Pydantic <code>model_dump()</code>。</p><h2 id="existing-http-routes" tabindex="-1">Existing HTTP routes <a class="header-anchor" href="#existing-http-routes" aria-label="Permalink to &quot;Existing HTTP routes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP route</th><th>新 endpoint / 归属</th></tr></thead><tbody><tr><td><code>GET /events</code></td><td>传输层事件订阅</td></tr><tr><td><code>POST /command</code></td><td>兼容 Wire 命令的传输适配</td></tr><tr><td><code>GET /api/health</code></td><td>Host health service</td></tr><tr><td><code>GET /api/app-info</code></td><td>Host application service</td></tr><tr><td><code>GET /api/runtime-state</code></td><td><code>task.get</code> + <code>sandbox.status</code> + 活动 run 状态</td></tr><tr><td><code>POST /api/yolo</code></td><td>Runtime approval policy</td></tr><tr><td><code>GET /api/settings</code></td><td>Application config service</td></tr><tr><td><code>GET /api/artifacts</code></td><td><code>userdir.tree</code>，约定 path=<code>artifacts</code></td></tr><tr><td><code>GET /api/artifacts/read</code></td><td><code>userdir.file.read</code></td></tr><tr><td><code>POST /api/artifacts/open</code></td><td>Host file-open service</td></tr><tr><td><code>GET /api/project-files</code></td><td><code>userdir.tree</code></td></tr><tr><td><code>GET /api/project-tree</code></td><td><code>userdir.tree</code></td></tr><tr><td><code>GET /api/new-session-options</code></td><td>TaskSpec option catalog</td></tr><tr><td><code>GET /api/thread-meta/{id}</code></td><td><code>task.get</code></td></tr><tr><td><code>POST /api/project-path</code></td><td>新建 Task 时写入 <code>UserDirConfig</code></td></tr></tbody></table><h2 id="existing-vs-code-messages" tabindex="-1">Existing VS Code messages <a class="header-anchor" href="#existing-vs-code-messages" aria-label="Permalink to &quot;Existing VS Code messages&quot;">​</a></h2><p>VS Code Webview 发出的消息完整集合：</p><table tabindex="0"><thead><tr><th>Webview message</th><th>新 endpoint / 归属</th></tr></thead><tbody><tr><td><code>userInput</code></td><td><code>run.start</code></td></tr><tr><td><code>requestHistoryReplay</code></td><td><code>session.get</code></td></tr><tr><td><code>setSandboxTarget</code></td><td>新建 Task 的 <code>SandboxConfig</code>；已有 Task 配置保持冻结</td></tr><tr><td><code>setYoloMode</code></td><td>Runtime approval policy</td></tr><tr><td><code>requestRuntimeOptions</code></td><td>TaskSpec option catalog + Host environment service</td></tr><tr><td><code>requestSlashCommands</code></td><td>Application command catalog</td></tr><tr><td><code>handoffProvider</code></td><td>Runtime control</td></tr><tr><td><code>permit</code> / <code>deny</code></td><td>Runtime approval</td></tr><tr><td><code>cancelRun</code></td><td><code>run.cancel</code></td></tr></tbody></table><p>VS Code 当前还会直接发送 <code>commands</code>、<code>get_config</code>、<code>list_threads</code>、<code>history</code>、<code>reset</code>、<code>resume</code>、 <code>client_features</code>、<code>capabilities</code>、<code>handoff_provider</code>、<code>permit</code>、<code>deny</code>、 <code>cancel</code> 和 <code>user</code>。这些命令可由 Wire adapter 映射到上面的 endpoint。</p><h2 id="existing-desktop-ipc" tabindex="-1">Existing Desktop IPC <a class="header-anchor" href="#existing-desktop-ipc" aria-label="Permalink to &quot;Existing Desktop IPC&quot;">​</a></h2><p>Desktop IPC 分为共享资源、运行控制和宿主能力。</p><p>共享资源：</p><ul><li><code>desktop:list-threads</code> → <code>task.list</code></li><li><code>desktop:get-thread-meta</code> → <code>task.get</code></li><li><code>desktop:resume-thread</code> → <code>task.open</code></li><li><code>desktop:delete-thread</code> → <code>task.delete</code></li><li><code>desktop:reset-session</code> → <code>task.create</code></li><li><code>desktop:request-history</code> → <code>session.get</code></li><li><code>desktop:get-sandbox-status</code> → <code>sandbox.status</code></li><li><code>desktop:list-sandbox-tree</code> → <code>sandbox.tree</code></li><li><code>desktop:list-project-files</code> / <code>desktop:list-project-tree</code> → <code>userdir.tree</code></li><li><code>desktop:list-artifacts</code> / <code>desktop:read-artifact</code> → <code>userdir.tree</code> / <code>userdir.file.read</code></li><li><code>desktop:send-user-input</code> → <code>run.start</code></li></ul><p>运行控制：</p><ul><li><code>desktop:set-yolo-mode</code></li><li><code>desktop:send-wire-command</code></li><li><code>desktop:permit-tool-call</code></li><li><code>desktop:deny-tool-call</code></li><li><code>desktop:clear-last-error</code></li></ul><p>宿主能力：</p><ul><li><code>desktop:get-app-info</code></li><li><code>desktop:get-runtime-state</code></li><li><code>desktop:get-settings</code></li><li><code>desktop:open-documentation</code></li><li><code>desktop:open-artifact</code></li><li><code>desktop:select-project</code></li><li><code>desktop:pick-directory</code></li><li><code>desktop:get-new-session-options</code></li><li><code>desktop:get-onboarding-state</code></li><li><code>desktop:refresh-environment-check</code></li><li><code>desktop:install-pagent-cli</code></li><li><code>desktop:save-provider-setup</code></li><li><code>desktop:complete-onboarding</code></li></ul><p>宿主能力保留在 Desktop 主进程。远程 HTTP 部署可以提供对应 Host service；核心资源 层无需依赖 Electron、VS Code 或 FastAPI。</p><h2 id="transport-wrapper-rules" tabindex="-1">Transport wrapper rules <a class="header-anchor" href="#transport-wrapper-rules" aria-label="Permalink to &quot;Transport wrapper rules&quot;">​</a></h2><ol><li>Wrapper 负责鉴权、超时、bytes 编码、错误码和连接生命周期。</li><li>Wrapper 不直接读取 Task 目录、Session 文件、Sandbox backend 或 UserDir 路径。</li><li>Task 配置只在 <code>task.create</code> 时写入，恢复任务使用 <code>task.open</code> 读取 <code>task.toml</code>。</li><li>API key、审批决定和客户端 feature negotiation 保持在运行时，不写入 <code>task.toml</code>。</li><li><code>ResourceService.close()</code> 在进程或请求作用域结束时释放已打开的 Sandbox 和 Session。</li></ol>',30)])])}const k=t(r,[["render",s]]);export{h as __pageData,k as default};
